import React, { useState, useEffect } from "react";
import { Search, MapPin, Briefcase, ArrowRight, CheckCircle } from "lucide-react";

const GAMYAM_COLORS = {
  darkBg: '#0f0f10',
  darkCard: '#2c2c2d',
  darkGray: '#4a4a4b',
  orange: '#ff7c26',
  orangeLight: '#f97211',
  textLight: '#ffffff',
  textSecondary: '#d8d8d8',
  textMuted: '#8e8e8e',
  border: '#3b3b3c',
  success: '#83ff76',
  info: '#2d62ff',
};

const mockJobs = [
  {
    _id: "1",
    title: "Senior Product Manager",
    department: "Product",
    location: "San Francisco, CA",
    type: "Full-time",
    experience: "5+ years",
    description: "Lead our product strategy and vision for enterprise solutions.",
    tags: ["Product Strategy", "Leadership", "Analytics"]
  },
  {
    _id: "2",
    title: "Full Stack Developer",
    department: "Engineering",
    location: "Remote",
    type: "Full-time",
    experience: "3+ years",
    description: "Build scalable applications using React, Node.js, and modern cloud infrastructure.",
    tags: ["React", "Node.js", "AWS"]
  },
  {
    _id: "3",
    title: "UX/UI Designer",
    department: "Design",
    location: "New York, NY",
    type: "Full-time",
    experience: "2+ years",
    description: "Design beautiful and intuitive user interfaces for our platform.",
    tags: ["UI Design", "Figma", "User Research"]
  },
  {
    _id: "4",
    title: "Data Analytics Engineer",
    department: "Data",
    location: "Remote",
    type: "Full-time",
    experience: "4+ years",
    description: "Transform raw data into actionable insights for business growth.",
    tags: ["SQL", "Python", "Analytics"]
  },
  {
    _id: "5",
    title: "Marketing Manager",
    department: "Marketing",
    location: "Los Angeles, CA",
    type: "Full-time",
    experience: "3+ years",
    description: "Drive go-to-market strategies and manage brand positioning.",
    tags: ["GTM", "Brand", "Analytics"]
  },
  {
    _id: "6",
    title: "DevOps Engineer",
    department: "Engineering",
    location: "Remote",
    type: "Full-time",
    experience: "3+ years",
    description: "Manage infrastructure and deployment pipelines for scale.",
    tags: ["Kubernetes", "CI/CD", "AWS"]
  },
];

export default function JobList() {
  const [jobs, setJobs] = useState(mockJobs);
  const [filteredJobs, setFilteredJobs] = useState(mockJobs);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedDept, setSelectedDept] = useState("All");

  const departments = ["All", "Engineering", "Product", "Design", "Data", "Marketing"];

  useEffect(() => {
    filterJobs();
  }, [searchTerm, selectedDept]);

  const filterJobs = () => {
    let filtered = jobs;

    if (selectedDept !== "All") {
      filtered = filtered.filter(job => job.department === selectedDept);
    }

    if (searchTerm) {
      filtered = filtered.filter(job => 
        job.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        job.description.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    setFilteredJobs(filtered);
  };

  return (
    <div style={styles.container}>
      {/* Hero Section */}
      <div style={styles.hero}>
        <div style={styles.heroContent}>
          <h1 style={styles.heroTitle}>Join Our Team</h1>
          <p style={styles.heroSubtitle}>
            We're building the future of enterprise solutions. Explore exciting career opportunities with GAMYAM.
          </p>
        </div>
      </div>

      {/* Stats Section */}
      <div style={styles.statsSection}>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>
            <Briefcase size={24} color={GAMYAM_COLORS.orange} />
          </div>
          <div>
            <div style={styles.statValue}>{jobs.length}</div>
            <div style={styles.statLabel}>Open Positions</div>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>
            <CheckCircle size={24} color={GAMYAM_COLORS.success} />
          </div>
          <div>
            <div style={styles.statValue}>500+</div>
            <div style={styles.statLabel}>Happy Employees</div>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>
            <MapPin size={24} color={GAMYAM_COLORS.info} />
          </div>
          <div>
            <div style={styles.statValue}>Global</div>
            <div style={styles.statLabel}>Work Locations</div>
          </div>
        </div>
      </div>

      {/* Search & Filter Section */}
      <div style={styles.searchSection}>
        <div style={styles.searchContainer}>
          <Search size={20} color={GAMYAM_COLORS.textMuted} style={{ position: 'absolute', left: '16px', top: '12px' }} />
          <input
            type="text"
            placeholder="Search positions by title or keywords..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={styles.searchInput}
          />
        </div>

        <div style={styles.filterContainer}>
          {departments.map((dept) => (
            <button
              key={dept}
              onClick={() => setSelectedDept(dept)}
              style={{
                ...styles.filterBtn,
                ...(selectedDept === dept ? styles.filterBtnActive : styles.filterBtnInactive)
              }}
            >
              {dept}
            </button>
          ))}
        </div>
      </div>

      {/* Jobs Grid */}
      <div style={styles.jobsSection}>
        {filteredJobs.length > 0 ? (
          <div style={styles.jobGrid}>
            {filteredJobs.map((job) => (
              <div key={job._id} style={styles.jobCard}>
                <div style={styles.jobHeader}>
                  <div>
                    <h3 style={styles.jobTitle}>{job.title}</h3>
                    <p style={styles.jobDepartment}>{job.department}</p>
                  </div>
                  <ArrowRight size={20} color={GAMYAM_COLORS.orange} />
                </div>

                <p style={styles.jobDescription}>{job.description}</p>

                <div style={styles.jobMeta}>
                  <div style={styles.metaItem}>
                    <MapPin size={16} color={GAMYAM_COLORS.textMuted} />
                    <span style={styles.metaText}>{job.location}</span>
                  </div>
                  <div style={styles.metaItem}>
                    <Briefcase size={16} color={GAMYAM_COLORS.textMuted} />
                    <span style={styles.metaText}>{job.type}</span>
                  </div>
                </div>

                <div style={styles.tagContainer}>
                  {job.tags.map((tag, idx) => (
                    <span key={idx} style={styles.tag}>{tag}</span>
                  ))}
                </div>

                <button style={styles.applyBtn}>
                  View Details
                  <ArrowRight size={16} />
                </button>
              </div>
            ))}
          </div>
        ) : (
          <div style={styles.noResults}>
            <h2 style={styles.noResultsTitle}>No positions found</h2>
            <p style={styles.noResultsText}>Try adjusting your search or filters to find available opportunities.</p>
          </div>
        )}
      </div>

      {/* CTA Section */}
      <div style={styles.ctaSection}>
        <h2 style={styles.ctaTitle}>Don't see the right role?</h2>
        <p style={styles.ctaText}>Send us your resume and let us know what you're interested in. We're always looking for top talent.</p>
        <button style={styles.ctaBtn}>Get in Touch</button>
      </div>
    </div>
  );
}

const styles = {
  container: {
    minHeight: "100vh",
    background: GAMYAM_COLORS.darkBg,
    fontFamily: "Inter, sans-serif",
  },
  hero: {
    background: `linear-gradient(135deg, ${GAMYAM_COLORS.darkBg} 0%, ${GAMYAM_COLORS.darkCard} 100%)`,
    padding: "80px 20px",
    textAlign: "center",
    borderBottom: `1px solid ${GAMYAM_COLORS.border}`,
  },
  heroContent: {
    maxWidth: "800px",
    margin: "0 auto",
  },
  heroTitle: {
    fontSize: "56px",
    fontWeight: "700",
    color: GAMYAM_COLORS.textLight,
    marginBottom: "16px",
    letterSpacing: "-1px",
  },
  heroSubtitle: {
    fontSize: "18px",
    color: GAMYAM_COLORS.textMuted,
    lineHeight: "1.6",
  },
  statsSection: {
    maxWidth: "1200px",
    margin: "-40px auto 60px",
    padding: "0 20px",
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
    gap: "20px",
    position: "relative",
    zIndex: "10",
  },
  statCard: {
    background: GAMYAM_COLORS.darkCard,
    border: `1px solid ${GAMYAM_COLORS.border}`,
    borderRadius: "12px",
    padding: "24px",
    display: "flex",
    alignItems: "center",
    gap: "16px",
    boxShadow: "0 4px 12px rgba(0,0,0,0.3)",
  },
  statIcon: {
    width: "48px",
    height: "48px",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    background: `${GAMYAM_COLORS.orange}15`,
    borderRadius: "8px",
  },
  statValue: {
    fontSize: "24px",
    fontWeight: "700",
    color: GAMYAM_COLORS.textLight,
  },
  statLabel: {
    fontSize: "13px",
    color: GAMYAM_COLORS.textMuted,
    marginTop: "4px",
  },
  searchSection: {
    maxWidth: "1200px",
